ltValue":"hero-and-callout knowledge page","id":"method","label":"Visual method","type":"text"},{"binding":{"mode":"variable","target":"structure"},"defaultValue":"visual evidence, labels, and modules work as one coherent page","id":"structure","label":"Composition rule","type":"textarea"},{"binding":{"mode":"generation","target":"aspectRatio"},"defaultValue":"4:5","id":"aspect-ratio","label":"Format","options":[{"label":"Portrait 4:5","value":"4:5"},{"label":"Tall 9:16","value":"9:16"},{"label":"Square 1:1","value":"1:1"},{"label":"Landscape 3:2","value":"3:2"}],"type":"aspect-ratio"}],"description":"Turn a topic into a beautiful visual learning plate with a clear information hierarchy.","generation":{"capability":"image-generation","defaultOperation":"generate","defaultVariationCount":1,"delivery":"webmcp-import","operations":["generate","edit","variation","upscale"],"preferredMimeTypes":["image/png","image/webp"],"provider":"codex"},"id":"collectible-field-guide","layout":{"arrangement":"prompt-left-output-right","mode":"seeded","preserveManualGeometry":true},"outputs":[{"aspectRatio":"4:5","count":1,"id":"primary","kind":"image","label":"Result","layoutHint":"hero","operations":["generate","edit","variation","upscale"],"required":true,"role":"primary"}],"preservation":[{"appliesTo":["method","structure"],"description":"Preserve the defining hero-and-callout knowledge page method and this composition obligation: visual evidence, labels, and modules work as one coherent page.","id":"creative-mechanism","label":"Creative mechanism","strength":"must"}],"prompt":{"agentInstructions":"Resolve all visible controls and reference obligations before generation. Produce one candidate by default and return it to the primary output slot.","body":"Turn a topic into a beautiful visual learning plate with a clear information hierarchy. Create an original, polished image for this brief: {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.","title":"Creative direction","variables":[{"defaultValue":"Pollinator-friendly balcony plants","id":"brief","label":"Creative brief","required":true,"type":"text"},{"defaultValue":"hero-and-callout knowledge page","id":"method","label":"Visual method","type":"string"},{"defaultValue":"visual evidence, labels, and modules work as one coherent page","id":"structure","label":"Composition rule","type":"string"}]},"schema":"prompt-canvas.prompt-workspace-template@2","source":{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Collectible field guide"},"status":"starter","tags":["knowledge brand","encyclopedia plate","visual field guide"],"thumbnail":{"alt":"First-party graphic preview for Collectible field guide, illustrating hero-and-callout knowledge page.","assetPath":"/recipe-thumbnails/original-systems/collectible-field-guide.svg"},"title":"Collectible field guide","version":1,"x-agent-authoring":{"generationDefault":1,"origin":"independent-first-party","reviewState":"owner-requested-original-authoring"},"x-discovery":{"badges":["No photo needed","Makes 1 image"],"collection":"original-systems","complexity":"guided","inputModes":["text"],"inputSummary":["A creative brief"],"intentAliases":["encyclopedia plate","visual field guide","collectible knowledge page"],"intents":["create"],"outputKinds":["image"],"preservationNeeds":[],"requiredInputSummary":["A short creative brief"],"subjectKinds":["person","object","place","concept"],"thumbnail":{"alt":"First-party graphic preview for Collectible field guide, illustrating hero-and-callout knowledge page.","src":"/recipe-thumbnails/original-systems/collectible-field-guide.svg"},"userPromise":"Turn a topic into a beautiful visual learning plate with a clear information hierarchy."},"x-presentation":{"advancedControlIds":[],"initialView":"canvas","primaryControlIds":["brief","method","structure","aspect-ratio"],"resultEmphasis":"hero","showPromptByDefault":false}}', 'prompt-canvas.prompt-workspace-template@2', 'sha256:be38aeb7c75e126d1951c6ac3a613623bd2240a2a4f88f3028bad449f13e29f8', 'Turn a topic into a beautiful visual learning plate with a clear information hierarchy. Create an original, polished image for this brief: {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.', NULL, '{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Collectible field guide"}', 'Initial official catalog publication.', '2026-09-03T00:00:00Z', '2026-09-03T00:00:00Z');
